from framework.graphs import DIAMOND_DAG, CYCLIC_GRAPH_6, Graph
import itertools
def closure(g):
    R=set()
    for u in g.nodes:
        st=[u]; seen=set()
        while st:
            n=st.pop()
            for m in g.neighbors(n):
                if m not in seen:
                    seen.add(m); st.append(m)
        for v in seen:
            if v!=u: R.add((u,v))
    return R
